const HE_SRC = { col:"data:image/webp;base64,", dep:"data:image/png;base64,", plate:"data:image/webp;base64,", pdep:"data:image/png;base64," };
const HE_WALL = { pos:"", idx:"" };

// --- All the Way to a Happy Ending (v033, 2026-11-17, decision 47): shot 12B on Orbital's LD curved wall; physical Subaru (proxy) on wheel blocks.
// HEcam-local (m, Z-up, +Y = shot forward, lens at (0,0,1.515), pitch -3, 35 mm on 23.76 mm, 1.85:1); web = (X, Z, -Y). Data: source/happyending (Claude Code handoff).
// Inner frustum: cube v001 from P = (0,0.5,1.515); march from the virtual eye (nDisplay-style: includes the virtual lamp post ~3 m ahead, inside the wall);
// colour = 12B plate where the shot camera saw the hit (plate depth test), else the cube. Verified vs Unreal GTs (SSIM, ceiling 0.918): -0.6 X 0.759, +0.6 X 0.731, +0.5 Z 0.823.
const HE = { C:[0, 0, 1.515], P:[0, 0.5, 1.515], O:[-0.7489, 0.4242], R:7.49, pitch:-3.0, th:Math.tan(37.497 / 2 * Math.PI / 180), aspect:1.85, res:[800, 432] };
HE.tv = HE.th / HE.aspect;
