function buildOM() {
  const g = new THREE.Group();
  const grid = new THREE.GridHelper(18, 36, 0x3a3a3a, 0x1e1e1e); grid.position.y = 0.01;
  const mask = new THREE.Mesh(new THREE.PlaneGeometry(18, 9), new THREE.MeshBasicMaterial({ visible:false }));
  g.add(grid);
  const grey = new THREE.MeshStandardMaterial({ color:0x8c8a84, roughness:0.95 });
  const gazebo = new THREE.Group();
  const deck = new THREE.Mesh(new THREE.CylinderGeometry(2.4, 2.4, 0.3, 8), grey); deck.position.y = 0.15; gazebo.add(deck);
  for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; const p = new THREE.Mesh(new THREE.BoxGeometry(0.15, 2.6, 0.15), grey); p.position.set(Math.cos(a) * 2.2, 1.6, Math.sin(a) * 2.2); gazebo.add(p); }
  const roof = new THREE.Mesh(new THREE.ConeGeometry(2.9, 1.2, 8), grey); roof.position.y = 3.5; gazebo.add(roof);
  gazebo.position.set(-3.5, 0, -4.5); g.add(gazebo);
  const house = new THREE.Mesh(new THREE.BoxGeometry(5, 3.2, 3), grey); house.position.set(5.5, 1.6, -6); g.add(house);
  const walkers = [];
  if (mannequinGeo) for (let i = 0; i < 2; i++) { const m = new THREE.Mesh(mannequinGeo, mannequinMat); g.add(m); walkers.push(m); }
  g.userData.walkers = walkers;
  g.rotation.y = Math.PI;

  return g;
}

